"Burrows":"Gömülür",
"Every foe has a trick":"Her düşmanın bir hilesi var",
"Foes carry kits: a rule of their own, such as shielding an ally or bursting when they die. A \"Kit ?\" chip means you have not studied that kind yet; study it and the chip names the kit. Hover it to read the rule":"Düşmanlar hüner taşır: bir müttefiki kalkanla korumak ya da ölünce patlamak gibi kendine ait bir kural. \"Hüner ?\" etiketi o türü henüz incelemediğin anlamına gelir; incele, etiket hünerin adını verir. Kuralı okumak için üzerine gel",
"Weak and resistant":"Zayıf ve dirençli",
"Above the foes you can see what this place is weak to and what it resists. Each hit has a type: Strike and most minions are physical, Soul Siphon and Reap shadow, Grave Chill frost, Corpse Explosion and poison rot. The right type hits harder":"Düşmanların üstünde bu yerin neye zayıf olduğunu ve neye direndiğini görürsün. Her vuruşun bir türü var: Vuruş ve çoğu hizmetkâr fiziksel, Ruh Emme ve Biç gölge, Mezar Soğuğu ayaz, Ceset Patlaması ve zehir çürüme. Doğru tür daha sert vurur",
"Sweep an outgrown gate":"Geride kalmış bir kapıyı süpür",
"A gate far below you can now be swept from its card: one watch wins the whole run at once, with #% kill XP and the usual spoils, but nothing to raise":"Çok altında kalan bir kapı artık kartından süpürülebilir: bir nöbet tüm koşuyu bir anda kazanır, %# öldürme XP'si ve her zamanki ganimetle, ama diriltilecek bir şey olmadan",
"Sweep · # watch":"Süpür · # nöbet",
"Win the whole run at once: one watch, kill XP at #%, gold, trophies and gear as usual; nothing raised, no events or doors. A secret master or the rival stops it at the boss room":"Tüm koşuyu bir anda kazan: bir nöbet, öldürme XP'si %#, altın, ganimet ve teçhizat her zamanki gibi; diriltme, olay ya da kapı yok. Gizli bir efendi ya da rakip onu boss odasında durdurur",
"Swept: the gate's dead never stood a chance":"Süpürüldü: kapının ölülerinin hiç şansı yoktu",
"kill XP #%, nothing raised":"öldürme XP'si %#, hiçbir şey diriltilmedi",
"Killed by damage of a type it was weak to":"Zayıf olduğu türden hasarla öldü",
"Undone by its weakness: it keeps an echo of its kind's kit":"Zayıflığıyla çözüldü: türünün hünerinin bir yankısını taşır",
"Keeps an echo of its kind's kit, at #% strength; kinds whose kit has no echo give +#% damage":"Türünün hünerinin bir yankısını %# güçle taşır; hünerinin yankısı olmayan türler +%# hasar verir",
