"The Hell Tower":"Cehennem Kulesi",
"As the gate the Trial is set in":"Sınavın kurulduğu kapı gibi",
"The living have no resistances":"Yaşayanların direnci yoktur",
"Each depth has one weakness and one resistance, the same every time, shown before you enter":"Her derinliğin bir zayıflığı ve bir direnci vardır, her seferinde aynı, girmeden önce gösterilir",
"Every hit has one of five damage types: Physical, Shadow, Frost, Fire and Rot":"Her vuruşun beş hasar türünden biri vardır: Fiziksel, Gölge, Ayaz, Ateş ve Çürüme",
"Where foes stand decides what they are weak to and what they resist":"Düşmanların durduğu yer neye zayıf olduklarını ve neye direndiklerini belirler",
"A weakness adds to the damage, a resistance takes from it, once, after armor and before any shield":"Zayıflık hasara ekler, direnç ondan alır, bir kez, zırhtan sonra ve kalkandan önce",
"Armor and resistance are separate: piercing beats armor, the right type beats resistance":"Zırh ve direnç ayrıdır: delme zırhı yener, doğru tür direnci yener",
"Strike, Echo, Hellfire, Cleave, Bone Spear and its Splinter, Thorns, Barbed Hide, the Spiked and Volley marks, bleeding, and every minion hit without a typed trait":"Vuruş, Echo, Hellfire, Cleave, Kemik Mızrak ve Kıymığı, Thorns, Dikenli Deri, Dikenli ve Yaylım nişanları, kanama ve türlü özelliği olmayan her hizmetkâr vuruşu",
"Soul Siphon and Chorus, Reap, Death's Toll, and Bloodfiend minions":"Ruh Emme ve Chorus, Biç, Ölümün Bedeli ve Kan İblisi hizmetkârlar",
"Grave Chill, the Deep Winter capstone, and Rimeborn, Glaciermaul and Shatterwrought minions (Shatterwrought alternates frost and fire)":"Mezar Soğuğu, Derin Kış zirvesi ve Kırağıdoğan, Buzul Tokmağı ve Kırıkdövme hizmetkârlar (Kırıkdövme ayaz ve ateşi sırayla kullanır)",
"Burns, and Cinderborn and Pyreheart minions":"Yanıklar ve Küldoğan ve Ateşyürek hizmetkârlar",
"Corpse Explosion, poison and blight, and Venomous, Necrotic, Plaguebearer and Witchrot minions":"Ceset Patlaması, zehir ve çürüme yarası ve Zehirli, Nekrotik, Veba Taşıyıcı ve Cadıçürüğü hizmetkârlar",
"Armor can roll Fire, Frost, Rot or Shadow resistance as a bonus line":"Zırh ek satır olarak Ateş, Ayaz, Çürüme ya da Gölge direnci atabilir",
"Each takes that much from hits, burns and wounds of its type, up to #%":"Her biri kendi türündeki vuruşlardan, yanıklardan ve yaralardan o kadar alır, en fazla %#",
"Physical damage has no resistance line: Constitution, armor sets and titles cover it":"Fiziksel hasarın direnç satırı yoktur: Dayanıklılık, zırh takımları ve unvanlar onu karşılar",
"Weapons and relics can roll Fire, Frost, Rot or Shadow damage as a bonus line: that much more damage of the type from you and your army":"Silahlar ve kalıntılar ek satır olarak Ateş, Ayaz, Çürüme ya da Gölge hasarı atabilir: senden ve ordundan o türden o kadar fazla hasar",
"A minion with Rimeborn resists frost, Cinderborn fire, Venomous or Necrotic rot, each by #%":"Kırağıdoğan bir hizmetkâr ayaza, Küldoğan ateşe, Zehirli ya da Nekrotik çürümeye direnir, her biri %#",
"Vanguards and menders hit physical; strikers hit with their place's type":"Öncüler ve onarıcılar fiziksel vurur; vurucular bulundukları yerin türüyle vurur",
"Frost-touched elites hit frost and chill, Burning elites hit fire and burn":"Ayaz Değmiş seçkinler ayazla vurur ve üşütür, Yanan seçkinler ateşle vurur ve yakar",
"Cinder Wave and Volatile bodies are fire, poison and blight are rot, bleeding is physical":"Kor Dalgası ve Uçucu cesetler ateştir, zehir ve çürüme yarası çürümedir, kanama fizikseldir",
"Iron Rain: foes also resist #% of physical damage":"Demir Yağmuru: düşmanlar fiziksel hasarın %#'ine de direnir",
"Soul Storm: your shadow damage is #% stronger":"Ruh Fırtınası: gölge hasarın %# daha güçlüdür",
"Soul Siphon, the Siphon skills and blight deal #% more. Foes crit #% less often and miss # blow in #":"Ruh Emme, Emme yetenekleri ve çürüme yarası %# daha fazla vurur. Düşmanlar %# daha seyrek kritik vurur ve #'da # darbeyi ıskalar",
"Soul Siphon, the Siphon skills and blight deal #% more":"Ruh Emme, Emme yetenekleri ve çürüme yarası %# daha fazla vurur",
"Gear drops #% more often and rolls bonus lines as if one tier higher. Foes wear heavier armor: #% tougher to hurt, and they resist #% of physical damage on top":"Teçhizat %# daha sık düşer ve ek satırlarını bir kademe yüksekmiş gibi atar. Düşmanlar daha ağır zırh giyer: %# daha zor yaralanır ve üstüne fiziksel hasarın %#'ine direnir",
"Foes wear heavier armor: #% tougher to hurt, and they resist #% of physical damage on top":"Düşmanlar daha ağır zırh giyer: %# daha zor yaralanır ve üstüne fiziksel hasarın %#'ine direnir",
"Every room starts with one Soul harvested, and you regain #% more mana each turn. Your shadow damage is #% stronger. Foes deal #% more damage":"Her oda bir Ruh toplanmış olarak başlar ve her tur %# daha fazla mana kazanırsın. Gölge hasarın %# daha güçlüdür. Düşmanlar %# daha fazla hasar verir",
