"Break it into bone dust":"Kemik tozuna dönüştür",
"Break the Throne of Ash":"Kül Tahtı'nı kır",
"Breaks a piece into bone dust":"Bir parçayı kemik tozuna çevirir",
"Brew":"Demle",
"Brew Healing Draught · # trophies":"Şifa İksiri demle · # ganimet",
"Brew Mana Tonic · # trophies":"Mana Tonik demle · # ganimet",
