"Brighter text and bolder bars":"Daha parlak yazı ve kalın çubuklar",
"Brutal":"Acımasız",
"Build":"İnşa et",
"Build up the necropolis. Each building has # levels and its bonus lasts for the rest of this game. The higher levels need bone dust, which you get by salvaging gear on the Gear tab":"Nekropolü inşa et. Her binanın # seviyesi var ve bonusu bu oyunun geri kalanında sürer. Yüksek seviyeler, Teçhizat sekmesinde teçhizat parçalayarak elde ettiğin kemik tozu ister",
"Buildings":"Binalar",
"Bulwark":"Siper",
"Burn bright... it is over so quickly":"Parlak yan... öyle çabuk bitiyor ki",
"Burning":"Yanıyor",
"Burst apart":"Parçalandı",
"Buy":"Satın al",
"Buy a #":"Bir # al",
"Buy from # wandering pedlars":"# gezgin satıcıdan satın al",
"Buy potions (drunk in battle with Q and W) and Grave Salts, buy or forge gear, empower minions at the Bone Altar, and sell what you do not need":"İksir (savaşta Q ve W ile içilir) ve Mezar Tuzu al, teçhizat al ya da döv, Kemik Sunağı'nda hizmetkârları güçlendir ve ihtiyacın olmayanı sat",
"Buzzing... so quiet now":"Vızıltı... şimdi öyle sessiz ki",
"By level":"Seviyeye göre",
