"Damage over time ticks at the end of each turn, ignores ward and armor, and wears off when you leave the room. A new dose of the same kind refreshes it rather than stacking. A Healing Draught cures you; Dark Mending cures your whole side. Foes with the Warded affix and minions with the Warded trait are immune":"Zamanla hasar her turun sonunda işler, kalkanı ve zırhı yok sayar ve odadan çıkınca geçer. Aynı türden yeni bir doz biriktirmek yerine onu yeniler. Bir Şifa İksiri seni iyileştirir; Karanlık Onarım tüm tarafını iyileştirir. Korunaklı ekli düşmanlar ve Korunaklı özellikli hizmetkârlar bağışıktır",
