"Deeper foes wear armor that blunts every hit you and your army land: E #%, D #%, C #%, B #%, A #%, S #%, Tower #%. Soul Siphon pierces #%, Bone Spear half (all of it with Impaler); Corpse Explosion, Reap and Death's Toll ignore it":"Daha derindeki düşmanlar senin ve ordunun her vuruşunu zayıflatan zırh giyer: E %#, D %#, C %#, B %#, A %#, S %#, Kule %#. Ruh Emme %# deler, Kemik Mızrak yarısını (Delici ile tamamını); Ceset Patlaması, Biç ve Ölümün Bedeli onu yok sayar",
