"Draws enemy blows":"Düşman darbelerini çeker",
"Draws enemy blows. When a foe picks a target, each vanguard counts # and everyone else (you included) counts #, so vanguards draw most blows. They take Taunt orders and stand in front of a Sundering Blow":"Düşman darbelerini çeker. Bir düşman hedef seçerken her öncü # sayılır, diğer herkes (sen dahil) #; bu yüzden darbelerin çoğunu öncüler çeker. Kışkırt emirlerini alırlar ve Parçalayan Darbe'nin önünde dururlar",
