"Drops improve with every floor. Studied entries show the tier mix at several heights":"Düşüşler her katta iyileşir. İncelenen kayıtlar birkaç yükseklikte kademe karışımını gösterir",
"Drought":"Kuraklık",
"Each day has # watches; a gate or the Tower uses one. These steps tick off as you play":"Her günün # nöbeti var; bir kapı ya da Kule birini harcar. Bu adımlar oynadıkça işaretlenir",
"Each day one cleared gate is cursed: harder, and pays more":"Her gün temizlenmiş bir kapı lanetlenir: daha zor ve daha çok öder",
"Each day one gate you have cleared is cursed with a twist that makes it harder. In return it pays double gold and trophies, more XP and more gear":"Her gün temizlediğin bir kapı onu zorlaştıran bir bükülmeyle lanetlenir. Karşılığında çift altın ve ganimet, daha çok TP ve daha çok teçhizat öder",
"Each dungeon you enter uses a watch. When the third is spent, the day closes":"Girdiğin her zindan bir nöbet harcar. Üçüncüsü bitince gün kapanır",
"Each follower falls #% of the time (Grave-bound never do); its gear returns to your bag. The Commander always comes home":"Her takipçi %# oranında düşer (Mezara bağlılar asla); teçhizatı çantana döner. Komutan her zaman eve döner",
"Each gate's gear is a set, and its unique counts toward it. Ordinary Tower gear belongs to no set":"Her kapının teçhizatı bir takımdır ve eşsizi de sayılır. Sıradan Kule teçhizatı hiçbir takıma ait değildir",
"Each has # levels, costing level #: # gold; level #: # gold + # bone dust; level #: # gold + # bone dust":"Her birinin # seviyesi var; seviye #: # altın; seviye #: # altın + # kemik tozu; seviye #: # altın + # kemik tozu",
"The Forge and the Ossuary cost one step less: level # at the level-# price, level # at the level-# price":"Demirci ve Kemiklik bir basamak ucuzdur: seviye # seviye # fiyatına, seviye # seviye # fiyatına",
"They last until New Game+":"Yeni Oyun+'a kadar kalır",
"Gold and bone dust grow with your level and your deepest open gate":"Altın ve kemik tozu seviyenle ve açık en derin kapınla büyür",
"Each has # levels, costing level #: # gold; level #: # gold + # bone dust; level #: # gold + # bone dust. They last until New Game+":"Her birinin # seviyesi var; seviye #: # altın; seviye #: # altın + # kemik tozu; seviye #: # altın + # kemik tozu. Yeni Oyun+'a kadar kalır",
"Each keeper paid in the same coin: a little more of themselves for every name. The tanner forgot his trade. The Warden forgot his family. The Sovereign forgot everything but the book. You check your own memories at night, and count them, and they are fewer":"Her bekçi aynı sikkeyle ödedi: her isim için kendinden biraz daha. Tabak zanaatını unuttu. Muhafız ailesini unuttu. Hükümdar kitap dışında her şeyi unuttu. Geceleri kendi anılarını yokluyor, sayıyorsun ve azalıyorlar",
"Each level gives # stat points and # skill point. Falling in a fight loses that room's spoils and #% of a level in XP. Going on to the next room heals #% of your HP, restores #% of your mana and heals your minions #%":"Her seviye # nitelik puanı ve # yetenek puanı verir. Bir dövüşte düşmek o odanın ganimetini ve bir seviyenin %#'i kadar TP'yi kaybettirir. Sonraki odaya geçmek canının %#'ini iyileştirir, mananın %#'ini geri verir ve hizmetkârlarını %# iyileştirir",
"Each mender wards you for #% of its attack":"Her şifacı saldırısının %#'i kadar seni korur",
"Earlier autosaves":"Önceki otomatik kayıtlar",
"Earned":"Kazanılan",
"Earned once, kept forever. Only the title you wear gives its bonus":"Bir kez kazanılır, sonsuza dek kalır. Bonusunu yalnızca giydiğin unvan verir",
"Easy for you":"Senin için kolay",
"Effects":"Efektler",
"Elder":"Kadim",
"Elite":"Seçkin",
"Elite affixes":"Seçkin ekleri",
"Elites are twice as common":"Seçkinler iki kat yaygın",
"Elites are twice as common. It touches every gate and the Tower until dawn":"Seçkinler iki kat yaygın. Şafağa kadar her kapıyı ve Kuleyi etkiler",
"Embers... only embers now":"Korlar... artık yalnızca korlar",
"Empower":"Güçlendir",
