"Empty":"Boş",
"Empty. Kill things and clear rooms to fill it":"Boş. Doldurmak için öldür ve oda temizle",
"Enchant":"Büyüle",
"Enemy strikers' crits make you bleed, and Cinder Waves burn. These tick at the end of each turn and ignore your ward. A Healing Draught cures you; Dark Mending cures your whole side":"Düşman vurucuların kritikleri seni kanatır, Kor Dalgaları yakar. Bunlar her turun sonunda işler ve kalkanını yok sayar. Bir Şifa İksiri seni iyileştirir; Karanlık Onarım tüm tarafını iyileştirir",
"English":"English",
"Enough. Let me show you what the book truly gave me":"Yeter. Sana kitabın bana gerçekte ne verdiğini göstereyim",
"Enraged":"Öfkeli",
"Enter":"Gir",
"Enter the Hell Tower and clear a floor":"Cehennem Kulesi'ne gir ve bir katı temizle",
"Enter the Rift":"Yarığa gir",
"Entries stay hidden until you kill the creature. Defeat one # times to study it and reveal its drop table. Ordinary enemies drop something #% of the time, elites #% with a lean toward better tiers, and bosses roll twice. Percentages are the share of drops":"Kayıtlar yaratığı öldürene kadar gizli kalır. İncelemek ve ganimet tablosunu açmak için birini # kez yen. Sıradan düşmanlar %# oranında bir şey düşürür, seçkinler %# ve daha iyi kademelere eğilimli, bosslar iki kez zar atar. Yüzdeler düşüşlerin payıdır",
"Epic":"Destansı",
"Epic gear · costs":"Destansı teçhizat · bedeli",
"Equip":"Kuşan",
"Equip it from your bag. Gear returns to the bag if it is released or shattered":"Çantandan kuşandır. Bırakılır ya da parçalanırsa teçhizatı çantaya döner",
"Equipment":"Donanım",
"Erases this character, its army, gear, skills and titles, and starts again on day #. Save slots are kept, so save to a slot first if you might want this character back":"Bu karakteri, ordusunu, teçhizatını, yeteneklerini ve unvanlarını siler ve gün #'den yeniden başlar. Kayıt yuvaları korunur; bu karakteri geri isteyebilirsen önce bir yuvaya kaydet",
"Eternal":"Ebedi",
"Eternal, the last form":"Ebedi, son biçim",
"Every creature, yours or the enemy's, has one of four roles":"Seninki ya da düşmanınki, her yaratığın dört rolden biri vardır",
"Every downed minion rises at full HP and the rest heal fully; you heal #% of your max HP, and your army deals #% more damage for # turns":"Yere düşen her hizmetkâr tam canla kalkar, diğerleri tamamen iyileşir; sen azami canının %#'i kadar iyileşirsin ve ordun # tur boyunca %# daha fazla hasar verir",
"Every fight begins with a ward worth #% of your max HP":"Her dövüş, azami canının %#'i değerinde bir kalkanla başlar",
"Every foe is frozen for # turns (bosses #), breaking any charging move, and takes #% more damage for # turns":"Her düşman # tur donar (bosslar #), güç toplayan her hamleyi bozar ve # tur boyunca %# daha fazla hasar alır",
"Every foe is shielded":"Her düşman kalkanlandı",
"Every foe mends":"Her düşman onarılıyor",
"Every foe takes #% of your Siphon, ignoring armor. Foes other than bosses left below #% HP die outright":"Her düşman Emmenin %#'i kadar hasar alır, zırhı yok sayar. Canı %#'in altında kalan boss dışı düşmanlar anında ölür",
"Every kill leaves a body. Raising costs mana and can fail; your first never does. Will and level lift the odds":"Her öldürme bir ceset bırakır. Diriltmek mana ister ve başarısız olabilir; ilki asla olmaz. İrade ve seviye şansı artırır",
"Every gate boss has a signature move it uses every few turns in place of attacking. Moves marked telegraphed are announced a turn ahead (Charging): soak them with Bone Ward, or freeze the boss with Grave Chill to cancel them. A boss calls at most # helpers a fight. Tower wardens borrow these moves, a turn sooner from floor #, and grow wrathful after turn #: every turn after that they hit #% harder (#% on floor #)":"Her kapı bossunun birkaç turda bir saldırmak yerine kullandığı imza bir hamlesi vardır. Önceden belli işaretli hamleler bir tur önceden duyurulur (Güç Topluyor): Kemik Kalkanı ile em ya da iptal etmek için bossu Mezar Soğuğu ile dondur. Bir boss dövüş başına en fazla # yardımcı çağırır. Kule muhafızları bu hamleleri ödünç alır, kat #'den itibaren bir tur erken, ve tur #'ten sonra gazaplanır: ondan sonra her tur %# daha sert vururlar (kat #'de %#)",
"Every kill restores # mana":"Her öldürme # mana verir",
"Every kill restores # mana and heals you for #% of your max HP":"Her öldürme # mana verir ve seni azami canının %#'i kadar iyileştirir",
"Every name in this book answers to you":"Bu defterdeki her isim sana boyun eğer",
"Each minion has a trait. It evolves # and # levels after it rose: stronger, with another trait":"Her hizmetkârın bir özelliği var. Dirildiği seviyenin # ve # üstünde evrilir: daha güçlü, bir özellik daha",
"Every raised minion rolls one trait (bosses two). It evolves at set levels above the level it was raised at; each stage adds its own buff and one more trait. A raised elite also keeps one of its affixes as a trait. Fusion can stack traits up to #":"Diriltilen her hizmetkâr bir özellik alır (bosslar iki). Diriltildiği seviyenin belirli seviyeler üstünde evrilir; her evre kendi güçlendirmesini ve bir özellik daha ekler. Diriltilen bir seçkin eklerinden birini de özellik olarak korur. Birleştirme #'e kadar özellik biriktirebilir",
"Every room holds one more foe":"Her odada bir düşman fazla",
"Every run begins with # Souls already harvested":"Her koşu # Ruh toplanmış olarak başlar",
"Every run so far (New Game+ runs included)":"Şimdiye kadarki her koşu (Yeni Oyun+ koşuları dahil)",
"Every soul here wears my iron. You will too":"Buradaki her ruh demirimi taşır. Sen de taşıyacaksın",
"Every torn page has found its way home, and the Ledger is whole in a way it never was. On the final page is the scribe's last instruction: whoever holds the book may close it forever by writing their own name. Your pen hovers over the page. Not yet":"Her yırtık sayfa yuvasını buldu ve Defter hiç olmadığı kadar bütün. Son sayfada kâtibin son talimatı var: kitabı tutan, kendi adını yazarak onu sonsuza dek kapatabilir. Kalemin sayfanın üstünde asılı. Henüz değil",
"Everything gear can give":"Teçhizatın verebileceği her şey",
"Everything that dies comes to me in the end. Why hurry":"Ölen her şey sonunda bana gelir. Neden acele",
"Everything you kill can be raised. The deeper the gate, the stronger the dead":"Öldürdüğün her şey diriltilebilir. Kapı ne kadar derinse ölüler o kadar güçlü",
"Evolution":"Evrim",
"Evolution buffs":"Evrim güçlendirmeleri",
"Evolve a minion":"Bir hizmetkârı evrimleştir",
"Evolve a minion into an Ancient":"Bir hizmetkârı Eski'ye evrimleştir",
"Evolve a minion into an Eternal":"Bir hizmetkârı Ebedi'ye evrimleştir",
"Evolve a minion into its Elder form":"Bir hizmetkârı Kadim biçimine evrimleştir",
"Evolves at Lv #":"Sv #'de evrilir",
"Execute":"İnfaz",
"Fair fight":"Dengeli dövüş",
"Fair for you":"Senin için dengeli",
"Faith":"İnanç",
"Fall # times":"# kez düş",
"Fallen foes drop trophies. Sell them at the Market, forge six from one gate into gear, or brew four into a potion":"Düşen düşmanlar ganimet bırakır. Pazarda sat, bir kapıdan altısını teçhizata döv ya da dördünü iksire demle",
"Come back stronger, or try an easier gate":"Daha güçlü dön ya da daha kolay bir kapı dene",
"Falls":"Düşüyor",
"Far to the east a tower of red stone has stood for as long as the valley has had a name. Tonight a light came on in its lowest window. The Ledger turned, unbidden, to a page headed with a single word: Climb":"Doğuda uzakta, vadinin adı olduğundan beri kızıl taştan bir kule duruyor. Bu gece en alt penceresinde bir ışık yandı. Defter kendiliğinden, başında tek bir kelime yazan bir sayfaya döndü: Tırman",
