"Five of them now, following you through the market at dawn. They carry your bags. They stand in the rain without complaint. One of them hums a song from a village that burned a century ago, and the others, slowly, have learned the words":"Şimdi beş tane, şafakta pazarda peşinden geliyorlar. Çantalarını taşıyorlar. Yağmurda şikâyet etmeden duruyorlar. Biri bir yüzyıl önce yanan bir köyden bir şarkı mırıldanıyor ve diğerleri yavaş yavaş sözlerini öğrendi",
