"From Venomous minions and the Grave Gas upgrade of Corpse Explosion. #% of the poisoner's attack (Grave Gas: #% of your Siphon) each turn for # turns":"Zehirli hizmetkârlardan ve Ceset Patlaması'nın Mezar Gazı yükseltmesinden. # tur boyunca her tur zehirleyenin saldırısının %#'i (Mezar Gazı: Emmenin %#'i)",
