"From level # the Old Shrine on the Town tab takes an oath. Devotion grows with the days you keep it: the gift grows x# after # days and x# after #; the price stays as it is. Renouncing costs # gold per level and starts devotion over. Swearing and renouncing happen in town":"Seviye #'den itibaren Kasaba sekmesindeki Eski Tapınak bir ant kabul eder. Bağlılık tuttuğun günlerle büyür: armağan # gün sonra x#, # gün sonra x# büyür; bedel olduğu gibi kalır. Vazgeçmek seviye başına # altına mal olur ve bağlılığı sıfırlar. Ant içmek ve vazgeçmek kasabada olur",
"From level #, choose one ultimate on the Skills tab (switch for free in town). With # Souls, unleash it in battle with R; it uses your turn and all your Souls":"Seviye #'den itibaren Yetenekler sekmesinden bir nihai seç (kasabada bedava değiştir). # Ruh ile savaşta R ile salıver; turunu ve tüm Ruhlarını harcar",
