"Minions keep the level they had, share half of each room's XP, and grow up to two levels above you. One downed in a fight may shatter when the room ends (less often with more Will; never if Grave-bound); otherwise it binds back together. Released or shattered gear-bearers return their gear to your bag":"Hizmetkârlar sahip oldukları seviyeyi korur, her odanın TP'sinin yarısını paylaşır ve senden iki seviye yükseğe kadar büyür. Dövüşte yere düşen biri oda bitince parçalanabilir (daha çok İrade ile daha seyrek; Mezara bağlıysa asla); yoksa yeniden birleşir. Serbest bırakılan ya da parçalanan teçhizat taşıyıcılar teçhizatlarını çantana döndürür",
"Most foes slain in one run":"Bir koşuda en çok öldürülen düşman",
"Most gold from one run":"Bir koşuda en çok altın",
"Moves marked Charging land next turn. Raise Bone Ward to soak the hit, or freeze the boss with Grave Chill to break its focus and cancel the move":"Güç Topluyor işaretli hamleler bir sonraki turda iner. Darbeyi emmek için Kemik Kalkanı kaldır ya da odağını bozup hamleyi iptal etmek için bossu Mezar Soğuğu ile dondur",
"Music":"Müzik",
"My children ate your Rat King's court, little scribe. Now they are hungry again":"Çocuklarım Rat King'inin sarayını yedi, küçük kâtip. Şimdi yine açlar",
"My children grow so quietly. You will make a fine tree":"Çocuklarım öyle sessiz büyür ki. Sen de güzel bir ağaç olursun",
"My court! To me, all of you, to me":"Sarayım! Bana, hepiniz, bana",
"NG+#":"YO+#",
"Names of places, foes and items stay in English":"Yer, düşman ve eşya adları İngilizce kalır",
