"Necromancer rank":"Ölüçağıran rütbesi",
"Necrotic Edge":"Nekrotik Ağız",
"Needs a body that fell this room":"Bu odada düşmüş bir ceset gerekir",
"Never shatters when downed":"Yere düşünce asla parçalanmaz",
