"New Game+ #":"Yeni Oyun+ #",
"New contracts every dawn. Claim finished ones in town; unclaimed ones lapse without penalty":"Her şafakta yeni sözleşmeler. Bitenleri kasabada al; alınmayanlar cezasız düşer",
"New game":"Yeni oyun",
