"What each body rises with at its gate's base foe level, before Will, Grave Pact, gear, traits and evolution":"Her cesedin kapısının temel düşman seviyesinde, İrade, Mezar Andı, teçhizat, özellikler ve evrimden önce dirildiği güç",
