"Uncommon gear · costs":"Az Bulunur teçhizat · bedeli",
"Under the keepers' graves lie older things, masters who held the book before it was a book, when it was only a hunger in the dark. Oswin did not create the Ledger. He gave a shape to something that was already there, waiting to be written down":"Bekçilerin mezarlarının altında daha eski şeyler yatar; kitap henüz kitap değilken, karanlıkta yalnızca bir açlıkken onu tutan efendiler. Oswin Defteri yaratmadı. Zaten orada olan, yazılmayı bekleyen bir şeye biçim verdi",
