"When the two halves meet, the Ledger will hold every name above and below. Whoever keeps it then will not rule the dead. They will be the dead's memory, the only thing between every soul and nothing. It is not a crown. It is a weight":"İki yarı buluştuğunda Defter yukarıdaki ve aşağıdaki her ismi tutacak. O zaman onu tutan ölülere hükmetmeyecek. Ölülerin hafızası olacak, her ruhla hiçlik arasındaki tek şey. Bu bir taç değil. Bir yük",
