"Your skills are silenced for # turns and every foe mends":"Yeteneklerin # tur susturuldu ve her düşman onarılıyor",
"Your squads come back with gold you did not earn and stories they cannot tell. The gates you cleared are being cleared again in your name, while you sleep. Somewhere a village has started telling tales of a dead captain who marches past at midnight and harms no one who keeps their door shut":"Bölüklerin senin kazanmadığın altınla ve anlatamadıkları hikâyelerle dönüyor. Temizlediğin kapılar sen uyurken adına yeniden temizleniyor. Bir yerde bir köy, gece yarısı geçip giden ve kapısını kapalı tutan kimseye zarar vermeyen ölü bir yüzbaşının hikâyelerini anlatmaya başladı",
"Your target takes #% more damage from every source for # turns":"Hedefin # tur boyunca her kaynaktan %# daha fazla hasar alır",
