"Now: +# army slots, +# Reserve places":"Şu an: +# ordu yeri, +# Yedek yeri",
"# Reserve places":"# Yedek yeri",
"A bench for minions you keep but do not take along. They do not fight, take damage or earn XP, and keep their gear. Moving one in or out is free, in town":"Tutup yanına almadığın hizmetkârlar için bir yedek sırası. Savaşmazlar, hasar almazlar, TP kazanmazlar ve teçhizatlarını korurlar. Birini içeri ya da dışarı almak kasabada bedavadır",
"Back from a raid, with no room in your army or the Reserve. Make room, or let one go":"Akından döndüler, ama ordunda da Yedekte de yer yok. Yer aç ya da birini bırak",
"Raise to the Reserve · #% · # mana":"Yedeğe dirilt · %# · # mana",
"Your army is full: the minion goes to the Reserve":"Ordun dolu: hizmetkâr Yedeğe gider",
"The Reserve has # free place: raise into it, or release someone":"Yedekte # boş yer var: oraya dirilt ya da birini serbest bırak",
"The Reserve has # free places: raise into it, or release someone":"Yedekte # boş yer var: oraya dirilt ya da birini serbest bırak",
"# went to the Reserve: your army is full":"# tanesi Yedeğe gitti: ordun dolu",
"# wait at the gate: your army and Reserve are full":"# tanesi kapıda bekliyor: ordun ve Yedek dolu",
"Your army list now has a Reserve below it: a bench for minions you want to keep but not take along. Benched minions do not fight or grow. Moving one in or out is free, in town. When your army is full, a raised body can go straight to the Reserve":"Ordu listenin altında artık bir Yedek var: tutmak isteyip yanına almadığın hizmetkârlar için bir yedek sırası. Yedekteki hizmetkârlar savaşmaz ve gelişmez. Birini içeri ya da dışarı almak kasabada bedavadır. Ordun doluyken diriltilen bir ceset doğrudan Yedeğe gidebilir",
"Opens with the Town tab: # places, +# per Crypt level. Benched minions do not fight, take damage or earn XP, and keep their gear. Moving one is free, in town; a full army can raise straight into it":"Kasaba sekmesiyle açılır: # yer, Kripta seviyesi başına +#. Yedekteki hizmetkârlar savaşmaz, hasar almaz, TP kazanmaz ve teçhizatlarını korur. Birini taşımak kasabada bedavadır; dolu bir ordu doğrudan oraya diriltebilir",
"A raid is an order for tonight: the squad fights the rest of today's runs with you and marches when the day ends. Odds are taken then, from whoever is left. Cancel any time before nightfall. Reserve minions can march too. Away overnight, each keeps its place in the army or the Reserve":"Akın bu gecenin emridir: bölük bugünün kalan seferlerinde seninle savaşır ve gün bitince yürür. Şans o an, geriye kim kaldıysa ondan hesaplanır. Gece çökmeden istediğin an iptal et. Yedekteki hizmetkârlar da yürüyebilir. Gece uzaktayken her biri orduda ya da Yedekte kendi yerini korur",
"Order the raid for tonight · #% odds":"Akını bu geceye emret · %# şans",
"War table · # tonight":"Savaş masası · bu gece #",
"#% odds now · marches at nightfall, back at dawn":"şu an %# şans · gece çökünce yürür, şafakta döner",
"#% odds now":"şu an %# şans",
"marches at nightfall, back at dawn":"gece çökünce yürür, şafakta döner",
"A raised elite can rise as a Commander (#%; a boss #%), and may become one when it evolves. Only elites and bosses can hold it, even through fusion. From the War table on the Gates tab, a Commander leads one to # followers (+# per evolution, +# for a boss) against a gate you have cleared. A raid is an order for tonight: the squad fights the rest of the day's runs with you and marches when the day ends, with whoever is still standing (no Commander, no raid). You can cancel the order any time before nightfall. Away overnight they keep their places in the army or the Reserve, so a siege raise cannot fill them, and at dawn they step back in. Only if those places are gone (a burned Crypt) do they wait at the gate":"Diriltilen bir seçkin Komutan olarak kalkabilir (%#; bir boss %#) ve evrilince Komutan olabilir. Birleştirmeyle bile yalnızca seçkinler ve bosslar taşıyabilir. Kapılar sekmesindeki Savaş masasından bir Komutan bir ile # takipçiyi (evrim başına +#, boss için +#) temizlediğin bir kapıya götürür. Akın bu gecenin emridir: bölük günün kalan seferlerinde seninle savaşır ve gün bitince, hâlâ ayakta kim varsa onlarla yürür (Komutan yoksa akın da yok). Emri gece çökmeden istediğin an iptal edebilirsin. Gece uzaktayken orduda ya da Yedekte yerlerini korurlar, bu yüzden bir kuşatma diriltmesi o yerleri dolduramaz; şafakta yerlerine dönerler. Yerleri gitmişse (yanan bir Kripta) kapıda beklerler",
"Taken when the squad marches: its total attack and HP against the gate's foes, raised #% per Commander evolution and #% for a boss. Between #% and #%":"Bölük yürürken hesaplanır: toplam saldırısı ve canı kapının düşmanlarına karşı; Komutan evrimi başına %#, boss için %# artar. %# ile %# arasında",
"One of your minions can lead. Open the War table under the Gates tab to order it and a squad against a gate you have cleared. They fight beside you until nightfall, march when the day ends and come back at dawn":"Hizmetkârlarından biri önderlik edebilir. Onu ve bir bölüğü temizlediğin bir kapıya göndermek için Kapılar sekmesinin altındaki Savaş masasını aç. Gece çökene dek yanında savaşırlar, gün bitince yürürler ve şafakta dönerler",
"The living march on the necropolis tonight. Raids march first: whoever you send will not be on the walls":"Yaşayanlar bu gece nekropole yürüyor. Önce akınlar yürür: kimi gönderirsen surlarda olmaz",
"The living march on the necropolis tonight, when the day ends":"Yaşayanlar bu gece, gün bitince nekropole yürüyor",
"The living march on the necropolis tomorrow at dusk":"Yaşayanlar yarın alacakaranlıkta nekropole yürüyor",
"Three waves, the last led by an Inquisitor Captain. Your buildings lend their strength; raids march before them":"Üç dalga, sonuncusunun başında bir Inquisitor Captain. Binaların güç verir; akınlar onlardan önce yürür",
"Read about sieges":"Kuşatmalar hakkında oku",
"Siege: tonight":"Kuşatma: bu gece",
"Siege: in # day":"Kuşatma: # gün sonra",
"Siege":"Kuşatma",
"Sieges":"Kuşatmalar",
