"Burned in the last siege. Its effects, siege perk included, are lost until it is repaired. Repairs cost gold only":"Son kuşatmada yandı. Kuşatma avantajı dahil etkileri onarılana dek yok. Onarım yalnızca altına mal olur",
"nothing until it is repaired":"onarılana dek hiçbir şey",
