"The town has sent its militia, its crossbows and its chaplains, and the Inquisition has sent a captain to lead them":"Kasaba milislerini, arbaletçilerini ve papazlarını gönderdi; Engizisyon da onlara önderlik etsin diye bir yüzbaşı yolladı",
"Between waves you heal as between rooms; nothing can be raised until the last wave falls":"Dalgalar arasında odalar arasındaki gibi iyileşirsin; son dalga düşene dek hiçbir şey diriltilemez",
"On home ground your downed minions never shatter":"Kendi toprağında yere düşen hizmetkârların asla parçalanmaz",
