"Hold, and the town pays: gold, bone dust and a piece of gear. Fall, and they burn one of your buildings until you repair it":"Dayanırsan kasaba öder: altın, kemik tozu ve bir parça teçhizat. Düşersen binalarından birini sen onarana dek yakarlar",
