"The living broke through":"Yaşayanlar yarıp geçti",
"You lose no XP, and none of your dead were lost: they dragged themselves back into the crypts before dawn":"TP kaybetmezsin ve ölülerinden hiçbiri kaybolmadı: şafaktan önce kendilerini kriptalara geri sürüklediler",
"Wait for dawn":"Şafağı bekle",
"The living march on the necropolis tomorrow at dusk. When the day ends they will be at the walls. The Codex has a page on sieges":"Yaşayanlar yarın alacakaranlıkta nekropole yürüyor. Gün bitince surların önünde olacaklar. Kodeks'te kuşatmalar üzerine bir sayfa var",
"Last night the necropolis held against the living: +# gold, +# bone dust":"Dün gece nekropol yaşayanlara karşı dayandı: +# altın, +# kemik tozu",
"Siege, wave # of #":"Kuşatma, dalga #/#",
