[ // the last page, the endings and the inscriptions (game-abbey.js, R3 PR B)
 ["Endings","Sonlar"],["The last page","Son sayfa"],["The Ledger lies open, and the pen is in your hand","Defter açık duruyor ve kalem senin elinde"],
 ["The Hunger is gone. What is left is a blank page and a choice Oswin never made. Answer now, or leave it: the page waits, and the gates stay open","Hunger gitti. Geriye boş bir sayfa ve Oswin'in hiç yapmadığı bir seçim kaldı. Şimdi yanıtla ya da bırak: sayfa bekler ve kapılar açık kalır"],
 ["Close the book","Kitabı kapat"],["Keep writing","Yazmaya devam et"],["Write your own name, and let the rest rest","Kendi adını yaz ve gerisinin dinlenmesine izin ver"],
 ["The Ledger is not finished with you. You are not finished with it","Defter seninle işini bitirmedi. Sen de onunla işini bitirmedin"],
 ["The Last Keeper","Son Bekçi"],["The Hand That Writes","Yazan El"],["Both Endings","İki Son"],["The Quiet Valley","Sessiz Vadi"],["The Keeper's Cycle","Bekçinin Döngüsü"],
 ["Gates are #% gentler for the whole cycle, rewards unchanged. Nothing rises until your first gate clear of the cycle","Kapılar tüm döngü boyunca %# daha yumuşak, ödüller aynı. Döngünün ilk kapı temizliğine dek hiçbir şey dirilmez"],
 ["The usual New Game+, and one gate boss returns in Ledger form: in its second phase from the start, its heart paid twice. Vane Abbey opens with the Throne and the way the book remembers","Olağan Yeni Oyun+ ve bir kapı bossu Defter biçiminde döner: baştan ikinci evresinde, kalbi iki kez ödenir. Vane Abbey, Taht ve kitabın hatırladığı yolla açılır"],
 ["Not yet","Henüz değil"],["Close the Ledger","Defteri kapat"],["The last page waits for your answer","Son sayfa yanıtını bekliyor"],["Open the Ledger","Defteri aç"],["An inscription waits to be written","Bir yazıt yazılmayı bekliyor"],
 ["Write one inscription · it stays in the Ledger for every cycle to come","Bir yazıt yaz · gelecek her döngü için Defterde kalır"],
 ["Close the book: write your own name on the last page","Kitabı kapat: son sayfaya kendi adını yaz"],["Keep writing: turn the last page and go on","Yazmaya devam et: son sayfayı çevir ve sürdür"],["End one cycle each way","Her iki yolla birer döngü bitir"],
 ["Of the Many","Çokların"],["Of the Fallen","Düşenlerin"],["Of the Tower","Kulenin"],["Of the Masters","Efendilerin"],["Of the Faithful","Sadıkların"],["Of the Rival","Rakibin"],
 ["# raises in the cycle","döngüde # diriltme"],["# headstones in the Memorial","Anıt'ta # mezar taşı"],["Hell Tower floor #","Cehennem Kulesi kat #"],["all six secret masters slain","altı gizli efendinin hepsi öldürüldü"],["an oath kept the whole cycle","tüm döngü boyunca tutulan bir yemin"],["the rival beaten # times in the cycle","rakip döngüde # kez yenildi"],
 ["+#% raise chance","+%# diriltme şansı"],["Each minion in the Memorial gives your army +#% max HP, up to #%","Anıt'taki her hizmetkâr ordunun azami canına +%# verir, en çok %#"],["The Tower can start at floor # from the first climb","Kule ilk tırmanıştan itibaren kat #'den başlayabilir"],
 ["A secret master drops one heart more","Bir gizli efendi bir kalp fazla düşürür"],["A new oath starts at the second rank of devotion","Yeni bir yemin bağlılığın ikinci derecesinden başlar"],["The rival comes to steal half as often","Rakip yarı sıklıkla çalmaya gelir"],
 ["Written","Yazıldı"],["The remembered way","Hatırlanan yol"],
 ["The Ledger is quiet","Defter sessiz"],["The Ledger is quiet. Nothing rises until your first gate clear of this cycle","Defter sessiz. Bu döngünün ilk kapı temizliğine dek hiçbir şey dirilmez"],["The Quiet Valley: nothing rises until your first gate clear of this cycle","Sessiz Vadi: bu döngünün ilk kapı temizliğine dek hiçbir şey dirilmez"],
 ["The quiet valley","Sessiz vadi"],["The open book","Açık kitap"],["The book stirs","Kitap kıpırdıyor"],
 ["You wrote your own name on the last page, in your own hand, and the Ledger closed on it like a door on a warm room. All over the valley the dead lay down. Not dead again: finished. The ones in your army looked at you once, the way a crew looks at a captain on the last morning, and then they were bones, and the bones were only bones. The town woke to a silence it had forgotten. Someone opened a window. Someone laughed. The river ran the right way, and no one could remember it ever running the other","Son sayfaya kendi adını, kendi elinle yazdın ve Defter sıcak bir odanın kapısı gibi üstüne kapandı. Vadinin her yanında ölüler uzandı. Yeniden ölü değil: tamamlanmış. Ordundakiler, bir tayfanın son sabah kaptanına baktığı gibi sana bir kez baktılar, sonra kemik oldular ve kemikler yalnızca kemikti. Kasaba unuttuğu bir sessizliğe uyandı. Biri bir pencere açtı. Biri güldü. Nehir doğru yöne aktı ve kimse onun hiç öteki yöne aktığını hatırlayamadı"],
 ["You did not write your name. You turned the page instead, and the page was not blank any more: it had a line on it, in your hand, that you do not remember writing. The Ledger is not finished with you. Your dead felt it; they stood a little straighter. The valley will not rest, and neither will you, and somewhere under the river the thing that wanted to be everyone has learned that it will never be you. Write. The book is listening","Adını yazmadın. Onun yerine sayfayı çevirdin ve sayfa artık boş değildi: üstünde senin elinden, yazdığını hatırlamadığın bir satır vardı. Defter seninle işini bitirmedi. Ölülerin bunu hissetti; biraz daha dik durdular. Vadi dinlenmeyecek, sen de dinlenmeyeceksin ve nehrin altında bir yerde herkes olmak isteyen şey asla sen olamayacağını öğrendi. Yaz. Kitap dinliyor"],
 ["For days the Ledger lay shut in your pack like an ordinary book, and you almost believed it. Then, at the gate you cleared, the pages turned on their own to the place where your name was written, and below it, in fresh ink, a new line had begun","Günlerce Defter çantanda sıradan bir kitap gibi kapalı durdu ve neredeyse inanacaktın. Sonra temizlediğin kapıda sayfalar kendiliğinden adının yazılı olduğu yere çevrildi ve altında, taze mürekkeple, yeni bir satır başlamıştı"],
 ["The Old Gods you swore to are quiet tonight, as if they had been waiting to hear how it ends","Yemin ettiğin Eski Tanrılar bu gece sessiz, sanki nasıl biteceğini duymayı bekliyorlarmış gibi"],
 ["The thing you swore to below the shrine laughs once, softly, and does not say whether it is pleased","Tapınağın altında yemin ettiğin şey bir kez, yumuşakça gülüyor ve memnun olup olmadığını söylemiyor"],
 ["You swore to no one, and no one comes to claim you","Kimseye yemin etmedin ve kimse seni almaya gelmiyor"],
 ["Somewhere in the valley the other scribe closes their own book unfinished. You beat them, and they know it","Vadinin bir yerinde öteki katip kendi kitabını bitirmeden kapatıyor. Onu yendin ve bunu biliyor"],
 ["The other scribe is still out there, writing. Some day the two of you will meet over the same grave","Öteki katip hâlâ orada bir yerde yazıyor. Bir gün ikiniz aynı mezarın başında karşılaşacaksınız"],
 ["The Memorial is a city of names now","Anıt artık bir adlar şehri"],["The Memorial holds more names than the town does","Anıt kasabadan daha çok ad taşıyor"],["The Memorial is small. You were careful with them","Anıt küçük. Onlara özen gösterdin"],
 ["One of yours stands at your shoulder, old enough to remember the first page","Seninkilerden biri omzunun yanında duruyor, ilk sayfayı hatırlayacak kadar yaşlı"],
 ["The Ledger keeps its last page shut until what waits under Vane Abbey has fallen. Open the drowned door with either of its keys, cross the Scriptorium and end the Hunger, and the book will ask you how it ends","Defter, Vane Abbey'nin altında bekleyen düşene dek son sayfasını kapalı tutar. Boğulmuş kapıyı anahtarlarından biriyle aç, Yazıhaneyi geç ve Hunger'ı bitir; kitap sana nasıl biteceğini soracak"],
 ["When the Hunger falls the Ledger opens at its last page and asks once each cycle. The page waits on the Gates tab: you can answer later, and the gates stay open. Either answer lets you keep playing the cycle; it decides what New Game+ becomes","Hunger düştüğünde Defter son sayfasına açılır ve her döngüde bir kez sorar. Sayfa Kapılar sekmesinde bekler: sonra yanıtlayabilirsin ve kapılar açık kalır. Her iki yanıt da döngüyü oynamayı sürdürmene izin verir; Yeni Oyun+'ın ne olacağını belirler"],
 ["Ledger inscriptions","Defter yazıtları"],["Each ending lets you write one inscription you earned in that cycle. Inscriptions are permanent and stay through every New Game+, at most #","Her son, o döngüde kazandığın bir yazıtı yazmana izin verir. Yazıtlar kalıcıdır ve her Yeni Oyun+ boyunca kalır, en çok #"]
].forEach(([k,v])=>{ if(!TR_DICT.has(k)) TR_DICT.set(k,v); });
