[["A night won at a gate","Bir kapıda kazanılan gece"],["Steps","Adımlar"],["Targets","Hedefler"],["Dawn","Şafak"],["On the road","Yolda"],
 ["Each night has three steps, each at the cube root of the odds: the Approach (#% less with no vanguard), the Fight (#% less with no striker or reaper; #% more per striker or reaper, at most #%; #% more or less per minion whose type the gate is weak to or resists; #% more for a bonded pair) and the Haul. A failed Approach loses the night and nothing else. A failed Fight ends the night: each follower may fall, but the Commander shields the first, once an expedition. A failed Haul halves what the squad carries; with no mender, each night's take is halved. A step stays between #% and #%",
  "Her gecenin üç adımı vardır, her biri şansın küp kökünde: Yaklaşma (öncü yoksa %# daha az), Dövüş (vurucu ya da biçici yoksa %# daha az; her vurucu ya da biçici için %# daha fazla, en çok %#; kapının zayıf ya da dirençli olduğu türden her yaratık için %# daha fazla ya da az; bağlı bir çift için %# daha fazla) ve Taşıma. Başarısız bir Yaklaşma geceyi kaybettirir, başka bir şeyi değil. Başarısız bir Dövüş geceyi bitirir: her takipçi düşebilir, ama Komutan ilkini sefer başına bir kez korur. Başarısız bir Taşıma bölüğün taşıdığını yarıya indirir; şifacı yoksa her gecenin kazancı yarıya iner. Bir adım %# ile %# arasında kalır"],
 ["A cleared gate (one or two nights). Today's cursed gate (one or two nights): steps #% harder, gold x#, two pieces of gear at most. Ten floors of the Hell Tower once your best is floor # (two nights): Tower trophies, half the gold, a warden's heart #% of nights. A hunt for a kind you have mastered (one night): the Fight #% harder, # of its trophies, or a boss's heart #% of nights. A scavenge near your deepest gate (one night): no Fight, bone dust and trophies, half the XP",
  "Temizlenmiş bir kapı (bir ya da iki gece). Bugünün lanetli kapısı (bir ya da iki gece): adımlar %# daha zor, altın x#, en çok iki parça teçhizat. En iyi katın # olunca Cehennem Kulesi'nin on katı (iki gece): Kule ganimetleri, altının yarısı, gecelerin %#'inde bir muhafız kalbi. Ustalaştığın bir türün avı (bir gece): Dövüş %# daha zor, # ganimeti, ya da gecelerin %#'inde bir boss kalbi. En derin kapının yakınında leş toplama (bir gece): Dövüş yok, kemik tozu ve ganimetler, TP'nin yarısı"],
 ["With nights left, the squad waits at dawn for your word: press on (spoils #% more for each night pressed, steps #% harder), the risky path (no Approach and spoils doubled, but a lost Fight costs the weakest follower outright) or come home now. Spoils come home with the squad",
  "Gece kaldıkça bölük şafakta emrini bekler: ilerle (zorlanan her gece için ganimet %# daha fazla, adımlar %# daha zor), riskli yol (Yaklaşma yok ve ganimet iki katı, ama kaybedilen bir Dövüş en zayıf takipçiye doğrudan mal olur) ya da şimdi eve dön. Ganimet bölükle birlikte eve gelir"],
 ["One night in ten that holds brings something on the road: a lost patrol of the living (the Embalmery keeps one, or the town calms), an old camp (bone dust) or another keeper's squad (win: spoils +#% that night; lose: a follower may fall)",
  "Tutan her on geceden biri yolda bir şey getirir: yaşayanlardan kaybolmuş bir devriye (Mumyahane birini saklar, yoksa kasaba sakinleşir), eski bir kamp (kemik tozu) ya da başka bir bekçinin bölüğü (kazanırsan o gece ganimet +%#; kaybedersen bir takipçi düşebilir)"],
 ["In battle, a Commander in your army gives one free order a room: Strike harder (your minions deal #% more damage this turn, #% with two Commanders) or Steady (every minion sheds one condition). An Elder Commander (evolved twice) also makes Taunt last a turn longer and Bone Shield #% stronger",
  "Savaşta ordundaki bir Komutan oda başına bir bedava emir verir: Daha sert vur (yaratıkların bu tur %# daha fazla hasar verir, iki Komutanla %#) ya da Sağlam dur (her yaratık bir durumdan kurtulur). Kadim bir Komutan (iki kez evrilmiş) ayrıca Kışkırt'ı bir tur uzatır ve Kemik Siper'i %# güçlendirir"]
].forEach(([k,v])=>{ if(!TR_DICT.has(k)) TR_DICT.set(k,v); });
